import type { DialogueEntry } from '../../../../types';
import { CharacterId } from '../../characters';
import { Portrait } from '../../portraits';
import { Background } from '../../backgrounds';

export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "翌朝、玉座の間はすっかり様変わりしていた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "玉座は奥の壁際まで押しやられ、ほこりよけの布をかぶせられている。広間の中央には長机がひとつ。その上に水の入ったグラスが二つ、白紙の評価シートの束、ペンが一本、そして折りたたんだ紙の札が立ててあり、「面接官」と書かれていた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "机の向かい、広い石畳を隔てたところに、椅子がひとつだけぽつんと置かれている。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）勇者が攻めてくる日より緊張する。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お一人目、聖騎士オルドリック様。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "入ってきた男は、銀白色の全身鎧に身を包んでいた。磨き抜かれたその輝きに、魔王は目を細めなければならなかった。男は椅子の前で足を止め、寸分の狂いもない角度で一礼してから、ようやく腰を下ろした。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "本日はよろしくお願いいたします。こちらが履歴書と、推薦状です。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "推薦状は七通あった。うち三通には、国王の印が押されていた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "竜を倒したことがあるそうだな。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "十一頭です。うち二頭は誤解でして、のちに和解しております。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "志望動機は。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "正直に申し上げますと、騎士団ではもう昇れるところまで昇ってしまいまして、毎日会議ばかりなのです。もう少し、挑みがいのある仕事がしたいと考えました。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）「挑みがい」と口にしたとき、この男は余を見ていた。まだ登ったことのない山を見上げるような目で。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "念のため確認させてください。御城での業務内容は、定期的な魔王討伐ということでよろしいでしょうか。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "はい。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "では、初回で討伐に成功した場合はどうなりますか。その場合は本採用という扱いでしょうか。それとも、退職金が出るのでしょうか。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）本気だ。この男は本気で退職金のことを聞いている。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "その点は、追って検討いたします。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "承知しました。それと、労災保険はありますか。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "ございます。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "あるのか。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "昨日、加入いたしました。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "オルドリックはうなずき、小さな手帳に何か書きつけた。ペンの握り方は剣を握るときと同じで、手首が少しもぶれない。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）この男は勝てる。勝てるかもしれない、ではない。勝てるのだ。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）そして余が求めているのは、勝てる者ではない。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "結果は追って連絡する。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "ありがとうございました。お手合わせできる日を楽しみにしております。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お二人目。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "扉が細く開き、それから、もう少しだけ開いた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "入ってきたのは子どもだった。頭には明らかに大きすぎる兜をかぶっていた。一歩進むたびに少しずり落ち、そのたびに彼はそれを少し押し上げる。背中には木の剣を背負っていて、刀身にはクレヨンで「せいけん」と書いてあった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "ぼくは、勇者トビーです。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……かけたまえ。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "トビーは椅子によじのぼった。足が床に届かない。彼はリュックから紙を一枚取り出し、両手で差し出した。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "これ、同意書です。お母さんが書いてくれました。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「息子トビーが魔王城の宿敵採用面接を受けることに同意します。夕飯がありますので、五時半までには帰してください。」署名の下に、小さな字でもう一行あった。「本人はとても真剣です。どうか怖がらせないでください。」", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "歳はいくつだ。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "九歳半です。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "なぜ余の宿敵になりたい。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "先生が「将来の夢」の作文を書きなさいって。みんなパン屋さんとか騎士って書くから、ぼくは誰も書いたことがないのにしたかったんです。それに、魔王さん、さみしそうだから。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "同意書を持つ魔王の手が、一瞬止まった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……誰がそんなことを。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "だって、貼り紙に「定期的に来訪できる方」って書いてあったもん。さみしくない人は、あんなにていねいに書かないよ。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）九歳半。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "トビーさん、何か特技はありますか。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "かくれんぼが得意です。あと、ぼく毎日来られます。家、山のすぐ下だから。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「毎日」と言うときの彼の声には、少しの迷いもなかった。証明するまでもないことのように。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "連絡帳にサインしてもらえますか。先生が、おうちの人か、上司の人にサインをもらいなさいって。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "開かれた連絡帳のページには、すでに一マス、きちんと書きこまれていた。「今日の活動：魔王をめんせつ。」", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王はサインした。三百年の歴史を背負った署名は画数が多く入り組んでいて、連絡帳の小さなマスには、どうにか押しこむのがやっとだった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "ありがとうございました。じゃあ、ぼく帰ります。このあと算数の宿題があるので。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は兜を押し上げて、帰っていった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お三人目は……その前に、倉庫へお茶の葉を取りにまいります。切らしかけておりますので。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "今か。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "すぐに戻ります。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は通用口から出ていった。一分ほどして、正面の扉が開いた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "入ってきたのは女性だった。ふわふわの金色の巻き髪に、丸眼鏡。魔王が一度も見たことのない、淡い紫のワンピース。彼女は椅子に腰かけると背筋を伸ばし、両手を膝の上でそろえた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "はじめまして。リンセと申します。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は手元の履歴書に目を落とした。整った字で、どの画も最後に右上へわずかにはね上がっている。百十年見てきた字だ。あらゆるスケジュール表に、あらゆる経費精算書に、そして昨日加入したばかりの労災保険の書類に。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "金色の巻き髪のふちから、黒い髪がひと筋のぞいていた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）セリン。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……これまでの経歴を聞かせてもらおう。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "御城のことはよく存じております。第七層の刃の罠は、作動までに二秒の遅れがあること。陛下のマントの左肩に、繕った穴があること。それから、口上を言い終えるたびに、こっそり水をひと口お飲みになること。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "それは内部情報だ。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "企業研究は、入念にしてまいりましたので。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "なぜ余の宿敵になりたい。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は少し間を置いた。眼鏡の奥の目が、静かに彼を見ていた。毎朝スケジュール表を差し出すときと、まったく同じ目だった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "勇者は歳をとります。膝を悪くして、かぶを育てに行ってしまいます。陛下に必要なのは、いなくならない者です。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は何も言わなかった。高窓の外をカラスが横切り、その影が長机の上を一瞬よぎった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）百十年。あれは一度も遅刻したことがない。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……結果は追って連絡する。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は立ち上がって一礼し、正面の扉から出ていった。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一分後、通用口が開いた。茶葉の缶を抱えたセリンが入ってくる。少し息が上がっていて、襟元には金色の髪が一本ついていた。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "面接はつつがなく進みましたか。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……つつがなく。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "では陛下、どなたを採用なさいますか。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "机の上には履歴書が三通並んでいる。一通には国王の印が押され、一通には保護者の同意書が添えられ、最後の一通の筆跡は、目を閉じていてもわかる。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）どれかひとつ、選ばねばならん。カレンダーは、まだ白紙のままだ。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
];
